                      <span className="text-gray-900 font-medium text-[11px]">
                        æœ¬åˆç´„ç‚ºåŸåˆç´„ {quote.id} ä¹‹ã€{quote.voTitle || 'å¾ŒåŠ æ–½å·¥é …ç›®æ˜ç´°'}ã€‘ç¨ç«‹å ±åƒ¹èˆ‡è¿½åŠ å”è­°ã€‚
                      </span>
