  // Open the receipt edit and review modal
  const handlePrintReceipt = (quote: Quotation, stageName: string, stageValue: number, stageIndex: number, isVO: boolean, remark: string) => {
    try {
      // 1. Detect and format date
      const dateMatch = remark.match(/\(ä»˜æ¬¾æ—¥æœŸ:\s*(\d{4}-\d{2}-\d{2})\)/);
      const initialDate = dateMatch ? dateMatch[1] : new Date().toISOString().split('T')[0];

      // 2. Format Received From
      const initialReceivedFrom = `${quote.customerName} - ${quote.address || "ç„¡åœ°å€"}`;

      // 3. Format Payment Purpose (Pay For)
      let initialPayFor = stageName;
      const hasTerm = /(ç¬¬ä¸€æœŸ|ç¬¬äºŒæœŸ|ç¬¬ä¸‰æœŸ|ç¬¬å››æœŸ|ç¬¬äº”æœŸ|ç¬¬å…­æœŸ|ç¬¬ä¸ƒæœŸ|ç¬¬å…«æœŸ|ç¬¬ä¹æœŸ|ç¬¬åæœŸ|ç¬¬\d+æœŸ|ç¬¬\d+æœŸ|è®¢é‡‘|è¨‚é‡‘)/.test(stageName);
      if (!hasTerm) {
        initialPayFor = `ç¬¬${stageIndex + 1}æœŸ${stageName}`;
      }
      if (isVO) {
        initialPayFor = `è¿½åŠ å·¥ç¨‹(VO) ${initialPayFor}`;
      }

      // 4. Format Payment Method (Pay By)
      let initialPayBy = 'FPS / éŠ€è¡Œè½‰è³¬';
      const lowerRemark = remark.toLowerCase();
      if (lowerRemark.includes('fps') || lowerRemark.includes('è½‰æ•¸å¿«')) {
        initialPayBy = 'FPS (è½‰æ•¸å¿«)';
      } else if (lowerRemark.includes('visa')) {
        initialPayBy = 'VISA';
      } else if (lowerRemark.includes('master') || lowerRemark.includes('mastercard')) {
        initialPayBy = 'Mastercard';
      } else if (lowerRemark.includes('ae') || lowerRemark.includes('american express')) {
        initialPayBy = 'AE (American Express)';
      } else if (lowerRemark.includes('cash') || lowerRemark.includes('ç¾é‡‘')) {
        initialPayBy = 'ç¾é‡‘ Cash';
      } else if (lowerRemark.includes('cheque') || lowerRemark.includes('æ”¯ç¥¨')) {
        initialPayBy = 'æ”¯ç¥¨ Cheque';
      } else if (lowerRemark.includes('transfer') || lowerRemark.includes('è½‰è³¬') || lowerRemark.includes('åŒ¯æ¬¾')) {
        initialPayBy = 'éŠ€è¡Œè½‰è³¬ Bank Transfer';
      }

      setReceiptEditModal({
        isOpen: true,
        quote,
        stageName,
        stageValue,
        stageIndex,
        isVO,
        remark,
        editDate: initialDate,
        editReceivedFrom: initialReceivedFrom,
        editAmount: stageValue,
        editPayFor: initialPayFor,
        editPayBy: initialPayBy
      });
    } catch (err) {
      showToast('é–‹å•Ÿæ”¶æ“šç·¨è¼¯å¤±æ•—ï¼', 'error');
      console.error(err);
    }
  };

  // Open the custom receipt edit and review modal
  const handlePrintCustomReceipt = (quote: Quotation) => {
    try {
      const initialDate = new Date().toISOString().split('T')[0];
      const initialReceivedFrom = `${quote.customerName} - ${quote.address || "ç„¡åœ°å€"}`;
      
      const migrated = migrateQuotation(quote);
      const mainFinancials = getQuoteFinancials(migrated);
      const hasAnyVO = migrated.variationOrders && migrated.variationOrders.length > 0;
      const voFinancials = getCombinedVOFinancials(migrated);
      const combinedGrandTotal = mainFinancials.grandTotal + (hasAnyVO ? voFinancials.grandTotal : 0);
      const mainCollected = mainFinancials.stageValues.reduce((sum, s) => s.isPaid ? sum + s.val : sum, 0);
      const voCollected = hasAnyVO ? voFinancials.stageValues.reduce((sum, s) => s.isPaid ? sum + s.val : sum, 0) : 0;
      const combinedCollected = mainCollected + voCollected;
      const combinedUncollected = combinedGrandTotal - combinedCollected;

      setReceiptEditModal({
        isOpen: true,
        quote,
        stageName: 'è‡ªè¨‚æ”¶æ“š',
        stageValue: combinedUncollected > 0 ? combinedUncollected : 0,
        stageIndex: -1, // Use -1 for custom receipt
        isVO: false,
        remark: '',
        editDate: initialDate,
        editReceivedFrom: initialReceivedFrom,
        editAmount: combinedUncollected > 0 ? combinedUncollected : 0,
        editPayFor: '', // Blank for manual user input as requested
        editPayBy: 'FPS / éŠ€è¡Œè½‰è³¬'
      });
    } catch (err) {
      showToast('é–‹å•Ÿè‡ªè¨‚æ”¶æ“šç·¨è¼¯å¤±æ•—ï¼', 'error');
      console.error(err);
    }
  };

